from backend.app.services.loader import load_document
from backend.app.services.chunker import convertTochunks
from pathlib import Path
from langchain_core.documents import Document
UPLOAD_DIR = Path("backend/data/uploads")

doc = [Document(page_content="word"*500,
               metadata={'source':'abstract.pdf'})]
# print(doc.type)
def test_to_chunk():
    chunks = convertTochunks(doc)
    print(chunks)
    assert all(len(c) <= 200 for c in chunks[-1].page_content)


if __name__=="__main__":
    test_to_chunk()

